// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes memory _data) public {
        Reverter reverter = new Reverter();
        bool ok = true;
        try c.forward(address(reverter), _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter { fallback() external payable { revert(); } }
